  proof.mark("M:966–972", "throwing planning metadata remains explicit unavailable metadata", nativeObservation);
  proof.mark("M:983", "metadata EACCES is not lexical scan exhaustion", nativeObservation);
  assert.equal(result.results[0].status, "unavailable");
