function captureClassifiesCloseFailure(evidenceRoot, proof) {
  const { owner, workspace, target, spec, budget, reader } = createCaptureHarness(evidenceRoot, "enumeration-capture-close");
  const descriptors = new Set();
  let rejectClose = true;
  let faultMonitor;
  proof.recover(() => {
    rejectClose = false;
    fs.openSync = native.openSync;
    fs.closeSync = native.closeSync;
    const recoveredBudget = new faultMonitor.SharedReadBudget(256 * 1024, owner);
    const recoveredReader = new faultMonitor.EventReader(evidenceRoot, recoveredBudget);
    owner.advanceCycle(); recoveredBudget.beginCycle();
    const recovered = faultMonitor.captureSettledFilesWithSharedCredits([spec], fs.realpathSync(workspace), recoveredReader, 64 * 1024);
    recoveredBudget.finalizeCycle();
    assert.ok(recovered);
    assert.equal(recovered.results[0].status, "captured");
    assert.equal([...descriptors].filter(descriptorOpen).length, 0);
    assert.equal(owner.accounting().retainedReaderDescriptors, 0);
    assert.equal(owner.accounting().currentOutstandingBytes, 0);
  });
  proof.safetyFallback(() => {
    for (const descriptor of descriptors) if (descriptorOpen(descriptor)) native.closeSync(descriptor);
  });
  fs.openSync = function trackedOpen(file, ...args) { const fd = native.openSync.call(this, file, ...args); if (samePath(file, target)) descriptors.add(fd); return fd; };
  fs.closeSync = function failedClose(fd, ...args) { if (rejectClose && descriptors.has(fd)) throw Object.assign(new Error("enumeration capture close failure"), { code: "EIO" }); const result = native.closeSync.call(this, fd, ...args); descriptors.delete(fd); return result; };
  syncFilesystemExports();
  faultMonitor = loadFreshMonitor(evidenceRoot, "capture-close-fault");
  const faultBudget = new faultMonitor.SharedReadBudget(256 * 1024, owner);
  const faultReader = new faultMonitor.EventReader(evidenceRoot, faultBudget);
  owner.advanceCycle(); faultBudget.beginCycle();
  const failedClose = faultMonitor.captureSettledFilesWithSharedCredits([spec], fs.realpathSync(workspace), faultReader, 64 * 1024);
  faultBudget.finalizeCycle();
  const nativeObservation = {
    outcome: failedClose,
    openDescriptors: [...descriptors].filter(descriptorOpen),
    retainedReaderDescriptors: owner.accounting().retainedReaderDescriptors,
    outstandingBytes: owner.accounting().currentOutstandingBytes,
  };
  proof.mark("M:1023–1025", "failed capture close transfers the actual descriptor to the owner", nativeObservation);
  proof.mark("M:1027", "admitted close failure returns explicit unavailable capture", nativeObservation);
  proof.mark("M:929–930", "capture queue can distinguish admitted close failure from admission deferral", nativeObservation);
  assert.ok(failedClose, "an admitted capture close failure must return explicit unavailable evidence, not admission deferral");
  assert.equal(failedClose.results[0].status, "unavailable");
  assert.equal(nativeObservation.openDescriptors.length, 1);
  assert.equal(nativeObservation.retainedReaderDescriptors, 1);
  return nativeObservation;
}

