function captureIdentityAndAdmissionControls(evidenceRoot, proof) {
  const make = (label) => {
    const root = path.join(evidenceRoot, label);
    fs.mkdirSync(root, { recursive: true });
    const target = path.join(root, "capture.log");
    fs.writeFileSync(target, "CAPTURE_IDENTITY_CONTROL");
    const parent = fs.lstatSync(root, { bigint: true });
    const spec = { path: target, parentRealPath: fs.realpathSync(root), parentDevice: parent.dev.toString(), parentInode: parent.ino.toString() };
    const owner = new CommandTelemetryOwner({ commandRoot: path.join(root, "command"), evidenceDirectory: path.join(root, "evidence"), commandId: label });
    return { root, target, spec, owner };
  };
  const observations = {};

  {
    const { root, spec, owner } = make("capture-spec-parent");
    const directoryTarget = path.join(root, "nonregular");
    fs.mkdirSync(directoryTarget);
    const directorySpec = { ...spec, path: directoryTarget };
    const budget = new monitor.SharedReadBudget(256 * 1024, owner);
    const reader = new monitor.EventReader(root, budget);
    budget.beginCycle();
    const result = monitor.captureSettledFilesWithSharedCredits([
      { ...spec, error: "preclassified output unavailable" },
      { ...spec, parentInode: `${spec.parentInode}-wrong` },
      directorySpec,
    ], fs.realpathSync(root), reader, 64 * 1024);
    budget.finalizeCycle();
    observations.specAndParent = result.results.map((item) => item.status);
    assert.deepEqual(observations.specAndParent, ["unavailable", "unavailable", "unavailable"]);
  }

  {
    const { root, target, spec, owner } = make("capture-admission");
    const budget = new monitor.SharedReadBudget(1, owner);
    const reader = new monitor.EventReader(root, budget);
    budget.beginCycle();
    assert.equal(budget.reserveExactBeforeRead(1, "exhaust"), true);
    const result = monitor.captureSettledFilesWithSharedCredits([spec], fs.realpathSync(root), reader, 64 * 1024);
    budget.finalizeCycle();
    observations.admissionDeferred = result === undefined;
    assert.equal(observations.admissionDeferred, true);
  }

  {
    const { root, target, spec, owner } = make("capture-short-read");
    let descriptor;
    fs.openSync = function trackedOpen(candidate, ...args) {
      const value = native.openSync.call(this, candidate, ...args);
      if (samePath(candidate, target)) descriptor = value;
      return value;
    };
    fs.readSync = function shortRead(fd, buffer, offset, length, position) {
      if (fd === descriptor) return native.readSync.call(this, fd, buffer, offset, Math.max(0, length - 1), position);
      return native.readSync.call(this, fd, buffer, offset, length, position);
    };
    syncFilesystemExports();
    const faultMonitor = loadFreshMonitor(root, "capture-short-read-fault");
    const budget = new faultMonitor.SharedReadBudget(256 * 1024, owner);
    const reader = new faultMonitor.EventReader(root, budget);
    budget.beginCycle();
    const result = faultMonitor.captureSettledFilesWithSharedCredits([spec], fs.realpathSync(root), reader, 64 * 1024);
    budget.finalizeCycle();
    observations.shortRead = result.results[0].status;
    restoreFilesystem();
    assert.equal(observations.shortRead, "unavailable");
  }

  {
    const { root, target, spec, owner } = make("capture-open-replacement");
    let replaced = false;
    fs.openSync = function replaceBeforeOpen(candidate, ...args) {
      if (samePath(candidate, target) && !replaced) {
        replaced = true;
        const replacement = `${target}.replacement`;
        native.writeFileSync(replacement, Buffer.alloc(native.statSync(target).size, 81));
        native.renameSync(replacement, target);
      }
      return native.openSync.call(this, candidate, ...args);
    };
    syncFilesystemExports();
    const faultMonitor = loadFreshMonitor(root, "capture-open-replacement-fault");
    const budget = new faultMonitor.SharedReadBudget(256 * 1024, owner);
    const reader = new faultMonitor.EventReader(root, budget);
    budget.beginCycle();
    const result = faultMonitor.captureSettledFilesWithSharedCredits([spec], fs.realpathSync(root), reader, 64 * 1024);
    budget.finalizeCycle();
    observations.openReplacement = result.results[0].status;
    restoreFilesystem();
    assert.equal(observations.openReplacement, "unavailable");
  }

  {
    const { root, target, spec, owner } = make("capture-post-read-replacement");
    let descriptor;
    let replaced = false;
    fs.openSync = function trackedOpen(candidate, ...args) {
      const value = native.openSync.call(this, candidate, ...args);
      if (samePath(candidate, target)) descriptor = value;
      return value;
    };
    fs.readSync = function replaceAfterRead(fd, ...args) {
      const bytes = native.readSync.call(this, fd, ...args);
      if (fd === descriptor && !replaced) {
        replaced = true;
        const replacement = `${target}.replacement`;
        native.writeFileSync(replacement, Buffer.alloc(native.statSync(target).size, 82));
        native.renameSync(replacement, target);
      }
      return bytes;
    };
    syncFilesystemExports();
    const faultMonitor = loadFreshMonitor(root, "capture-replacement-fault");
    const budget = new faultMonitor.SharedReadBudget(256 * 1024, owner);
    const reader = new faultMonitor.EventReader(root, budget);
    budget.beginCycle();
    const result = faultMonitor.captureSettledFilesWithSharedCredits([spec], fs.realpathSync(root), reader, 64 * 1024);
    budget.finalizeCycle();
    observations.postReadReplacement = result.results[0].status;
    restoreFilesystem();
    assert.equal(observations.postReadReplacement, "unavailable");
  }

  const nativeObservation = observations;
  for (const site of ["M:963", "M:974–975", "M:981", "M:987–992", "M:993–996", "M:997–1001", "M:1003–1004", "M:1005–1010", "M:1020–1021"]) {
    proof.mark(site, "capture planning/admission/identity failure branch remains unavailable or genuinely deferred", nativeObservation);
  }
  return nativeObservation;
}

function captureQueueBoundaryControls(evidenceRoot, proof) {
  const { owner, workspace, target, spec, budget, reader } = createCaptureHarness(evidenceRoot, "enumeration-capture-queue-controls");
  const invocationId = "97".repeat(12);
  let producerState = "open";
  const queue = new monitor.HostCaptureSettlementQueue(() => producerState);
  const request = {
    invocationId, workspaceRealPath: fs.realpathSync(workspace), specs: [spec], maxTotalBytes: 64 * 1024,
  };
  assert.equal(queue.addRequest(request), true);
  assert.equal(queue.addRequest(request), false);
  const invalidQueue = new monitor.HostCaptureSettlementQueue(() => "closed");
  assert.equal(invalidQueue.addRequest({ invocationId: "invalid", specs: [] }), false);
  const capture = (job) => {
    owner.advanceCycle(); budget.beginCycle();
    const result = monitor.captureSettledFilesWithSharedCredits(job.specs, job.workspaceRealPath, reader, job.maxTotalBytes);
    budget.finalizeCycle();
    return result;
  };
  assert.equal(queue.settleNext(capture, () => true), undefined);
  producerState = "closed";
  const unavailable = queue.settleNext(capture, () => true);
  const nativeObservation = {
    targetBytes: native.statSync(target).size,
    unavailableKind: unavailable?.kind,
    pendingAfterUnavailable: queue.hasPending(),
    duplicateRejected: true,
    invalidRejected: true,
  };
  for (const site of ["M:907", "M:908–913", "M:914–916", "M:933", "M:934–941"]) {
    proof.mark(site, "capture queue validates, owns, deduplicates, and finitely settles missing terminal", nativeObservation);
  }
  assert.equal(unavailable?.kind, "unavailable");
  assert.equal(queue.hasPending(), false);
  return nativeObservation;
}

async function captureQueueClosedOwnerIsPermanent(evidenceRoot, proof) {
  const { owner, workspace, spec, budget, reader } = createCaptureHarness(evidenceRoot, "enumeration-capture-closed-owner");
  const invocationId = "98".repeat(12);
  const queue = new monitor.HostCaptureSettlementQueue(() => "closed");
  const request = { invocationId, workspaceRealPath: fs.realpathSync(workspace), specs: [spec], maxTotalBytes: 64 * 1024 };
  queue.addRequest(request);
  queue.addTerminal({ invocationId, type: "invocation_terminal", outcome: "succeeded" });
  const capture = (job) => {
    owner.advanceCycle(); budget.beginCycle();
    const result = monitor.captureSettledFilesWithSharedCredits(job.specs, job.workspaceRealPath, reader, job.maxTotalBytes);
    budget.finalizeCycle();
    return result;
  };
  await owner.close();
  const settlement = queue.settleNext(capture, (id, terminal) => owner.commitHostEvidence(id, terminal));
  const nativeObservation = { settlement, pending: queue.hasPending(), ownerClosed: owner.closed };
  proof.mark("M:943–944", "permanently closed owner refusal settles unavailable rather than capacity deferral", nativeObservation);
  assert.equal(queue.hasPending(), false,
    "capture enrichment cannot remain retry-pending after owner admission is permanently closed");
  return nativeObservation;
}

