function eventOversizeRemainderRejects(evidenceRoot, proof) {
  const { directory, owner, budget, reader } = createEventHarness(evidenceRoot, "enumeration-event-oversize-remainder");
  const file = path.join(directory, `${"ae".repeat(12)}.jsonl`);
  fs.writeFileSync(file, "x".repeat(256 * 1024 + 1));
  let thrown;
  for (let turn = 0; turn < 5 && !thrown; turn += 1) {
    try { reader.poll(); } catch (error) { thrown = error; }
    budget.finalizeCycle();
    // The registered monitor's owner drain advances the shared cycle after
    // each poll. Without this the first 245760 bytes exhaust lifetime credit
    // before the genuine 262144-byte incomplete-line bound is reachable.
    owner.advanceCycle();
  }
  const nativeObservation = { thrown: thrown?.message, maxBufferedEventBytes: reader.maxBufferedEventBytes }; 
  proof.mark("M:464", "oversized incomplete event remainder rejects explicitly at the fixed byte bound", nativeObservation);
  assert.match(thrown?.message ?? "", /NO_OUTPUT_EVENT_LINE_TOO_LARGE/);
  return nativeObservation;
}

