function eventRetirementRequiresConclusiveRemoval(evidenceRoot, proof) {
  const { directory, reader } = createEventHarness(evidenceRoot, "enumeration-event-retire");
  const invocationId = "4".repeat(24);
  const jsonl = path.join(directory, `${invocationId}.jsonl`);
  const terminal = path.join(directory, `${invocationId}.terminal.json`);
  fs.writeFileSync(jsonl, `${JSON.stringify({ type: "event", marker: "RETAIN_JSONL" })}\n`);
  fs.writeFileSync(terminal, `${JSON.stringify({ type: "invocation_terminal", marker: "RETAIN_TERMINAL" })}\n`);
  let fault = true;
  proof.recover(() => {
    fault = false;
    faultReader.retire(invocationId);
    assert.equal(native.existsSync(jsonl), false);
    assert.equal(native.existsSync(terminal), false);
  });
  fs.rmSync = function noOpRetirement(candidate, ...args) {
    if (fault && (samePath(candidate, jsonl) || samePath(candidate, terminal))) return undefined;
    return native.rmSync.call(this, candidate, ...args);
  };
  syncFilesystemExports();
  const faultMonitor = loadFreshMonitor(evidenceRoot, "event-retire-fault");
  const faultReader = new faultMonitor.EventReader(directory, new faultMonitor.SharedReadBudget());
  faultReader.retire(invocationId);
  const nativeObservation = {
    jsonlExists: native.existsSync(jsonl),
    terminalExists: native.existsSync(terminal),
    hasPending: faultReader.hasPending(),
    retiredFileBytes: faultReader.retiredFileBytes,
  };
  for (const site of ["M:343", "M:344", "M:345", "M:348", "M:349", "M:350"]) {
    proof.mark(site, "retirement retains state and files until both removals are conclusive", nativeObservation);
  }
  assert.equal(nativeObservation.hasPending, false, "unavailable retirement must not keep final drain spinning");
  assert.equal(nativeObservation.jsonlExists, true, "no-op retirement must retain the JSONL source");
  assert.equal(nativeObservation.terminalExists, true, "no-op retirement must retain the terminal source");
  assert.equal(nativeObservation.retiredFileBytes, 0, "no bytes retire before removal succeeds");
  return nativeObservation;
}

