function counterQueuedFrameSurvivesSynchronousThrow(evidenceRoot, proof) {
  const { service, stdin } = createCounterPureLogicHarness(evidenceRoot, "enumeration-counter-queued-throw");
  const originalWrite = stdin.write;
  service.writeBlocked = true;
  service.send({ action: "sample", marker: "RETAIN_FRAME" });
  stdin.write = function queuedWriteThrow() { throw new Error("enumeration queued native write throw"); };
  service.writeBlocked = false;
  let thrown;
  try { service.flushQueue(); } catch (error) { thrown = error; }
  const nativeObservation = {
    scope: PURE_COUNTER_LOGIC_SCOPE,
    thrown: thrown?.message,
    queuedFrames: service.sendQueue.length,
    queuedBytes: service.sendQueueBytes,
  };
  proof.recover(async () => {
    // RP-QUEUED-FAILED-DELIVERY-RETENTION (test-only premise correction,
    // replaces RP-QUEUED-THROW-EXPLICIT-CLOSE per owner decision 3 of
    // 2026-09-28): a frame whose submission threw is not re-submitted by the
    // first close; re-submission would be a new retry path. The transport is
    // failed, the retained frame is recorded as a failed delivery with the
    // throw preserved (transportFailure is that very Error; the frame stays at
    // the queue head), and close completes native closure with that failure
    // retained and reported. Protected property: no close reports the failed
    // submission as healthy, and public recovery closes the service naturally
    // without manual cleanup.
    const retainedFailure = service.transportFailure;
    assert.ok(retainedFailure instanceof Error && /enumeration queued native write throw/.test(retainedFailure.message),
      "the synchronous submission throw is retained as the transport failure");
    let retainedFrames = 0;
    stdin.write = function recoveredWrite(frame) {
      if (/RETAIN_FRAME/.test(String(frame))) retainedFrames += 1;
      return originalWrite.apply(this, arguments);
    };
    service.writeBlocked = false;
    await assert.rejects(() => service.close(), (error) => error === retainedFailure,
      "the first close rejects with the identical retained Error");
    assert.equal(retainedFrames, 0, "a frame whose submission threw is not re-submitted by the first close");
    assert.equal(service.transportFailure, retainedFailure, "the failure stays retained after close, with the throw preserved");
    assert.equal(service.sendQueue.length, 1, "the failed delivery stays recorded at the queue head");
    assert.match(String(service.sendQueue[0]), /RETAIN_FRAME/, "the recorded failed delivery is the retained frame");
    assert.equal(service.child, undefined, "the first close completes natural closure");
    await service.close();
    assert.equal(retainedFrames, 0, "no later close re-submits the failed delivery");
  });
  proof.safetyFallback(() => stdin.end());
  proof.mark("M:692–695", "pure queue logic: frame remains owned when submission throws synchronously", nativeObservation);
  assert.equal(service.sendQueue.length, 1,
    "flush cannot remove a queued native frame before synchronous submission succeeds");
  return nativeObservation;
}

