async function ownerRegistrationAndProtocolControls(evidenceRoot, proof) {
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-owner-protocol",
  });
  const boundaryClients = [];
  proof.recover(async () => {
    await requireFulfilledRecovery(boundaryClients.map((client) => client.close()));
    await owner.close();
  });
  await owner.start();
  console.log("OWNERSHIP_ENUMERATION_CASE_STEP owner-registration-protocol-controls owner-started");
  const config = owner.configuration();
  const wrongRegistrations = [
    { label: "owner-id", configuration: { ...config, ownerId: "wrong" }, invocationId: "1".repeat(24) },
    { label: "permission", configuration: { ...config, permission: "wrong" }, invocationId: "2".repeat(24) },
    { label: "command-id", configuration: { ...config, commandId: "wrong" }, invocationId: "3".repeat(24) },
    { label: "invocation-id", configuration: config, invocationId: "invalid" },
  ];
  const wrongOutcomes = [];
  for (const registration of wrongRegistrations) {
    const wrongClient = new CommandTelemetryClient(registration.configuration, registration.invocationId);
    boundaryClients.push(wrongClient);
    const transportWitness = new Promise((resolve) => wrongClient.once("transportError", (error) => resolve(error.message)));
    const connectOutcome = await wrongClient.connect().then(
      () => ({ kind: "fulfilled" }),
      (error) => ({ kind: "rejected", message: error.message }),
    );
    const transportError = await transportWitness;
    console.log(`OWNERSHIP_ENUMERATION_CASE_STEP owner-registration-protocol-controls wrong-${registration.label}-${connectOutcome.kind}`);
    wrongOutcomes.push({ label: registration.label, connectOutcome, transportError });
    await wrongClient.close();
  }
  assert.equal(owner.invocations.size, 0);
  // This is a wrong KIND in the very first wire frame, before registration.
  // Wrong registration fields and post-registration unknown kinds are distinct.
  const wrongFirst = net.createConnection(owner.endpoint);
  const firstFrame = { bytes:"",writeCallback:false,eof:false,closed:false,error:"" };
  wrongFirst.on("data", chunk => { firstFrame.bytes += chunk.toString("utf8"); });
  wrongFirst.once("end", () => { firstFrame.eof = true; });
  wrongFirst.once("error", error => { firstFrame.error = error.message; });
  const firstClosed = new Promise(resolve => wrongFirst.once("close", () => { firstFrame.closed = true; resolve(); }));
  await new Promise((resolve,reject) => { wrongFirst.once("connect",resolve); wrongFirst.once("error",reject); });
  wrongFirst.write(`${JSON.stringify({kind:"request",opId:"unregistered",channel:"ordinary",maxBytes:1})}\n`, () => { firstFrame.writeCallback = true; });
  await firstClosed;
  assert.equal(firstFrame.closed,true,"pre-registration wrong-kind socket must natively close");
  assert.equal(owner.invocations.size,0,"wrong first frame cannot allocate an invocation");
  assert.match(firstFrame.bytes,/COMMAND_TELEMETRY_REGISTRATION_REJECTED/);

  const invocationId = "4".repeat(24);
  const client = new CommandTelemetryClient(config, invocationId);
  proof.recover(async () => { await client.close(); });
  await client.connect();
  console.log("OWNERSHIP_ENUMERATION_CASE_STEP owner-registration-protocol-controls client-connected");
  const originalWrite = owner.write;
  let refusedGrant;
  const refusedObserved = new Promise((resolve) => { refusedGrant = resolve; });
  const refusalTransport = new Promise((resolve) => client.once("transportError", resolve));
  owner.write = function observeInvalidGrant(connection, value, ...args) {
    const result = originalWrite.call(this, connection, value, ...args);
    if (value?.kind === "grant" && value.accepted === false) refusedGrant(value);
    return result;
  };
  client.write({ kind: "request", opId: "bad", channel: "ordinary", maxBytes: 1 });
  console.log("OWNERSHIP_ENUMERATION_CASE_STEP owner-registration-protocol-controls invalid-request-dispatched");
  const refusalOutcome = await Promise.race([
    refusedObserved.then((grant) => ({ kind: "grant", grant })),
    refusalTransport.then((error) => ({ kind: "transport-error", error })),
  ]);
  owner.write = originalWrite;
  console.log(`OWNERSHIP_ENUMERATION_CASE_STEP owner-registration-protocol-controls invalid-request-${refusalOutcome.kind}`);
  const refusal = refusalOutcome.grant;
  const nativeObservation = {
    wrongOutcomes,
    firstFrame,
    registrationsAfterWrongFrames: 0,
    invalidGrantOutcome: refusalOutcome.kind,
    invalidGrantAccepted: refusal?.accepted,
    invalidGrantTransportError: refusalOutcome.error?.message,
    pendingRequests: owner.accounting().pendingRequests,
  };
  proof.mark("O:329–334", "every registration identity field rejects independently before invocation allocation", nativeObservation);
  proof.check("O:370–375", "invalid request is refused rather than queued or granted", nativeObservation, () => {
    assert.equal(refusalOutcome.kind, "grant", "invalid request must settle by explicit refusal rather than ambiguous transport loss");
    assert.equal(refusal?.accepted, false);
    assert.equal(owner.accounting().pendingRequests, 0);
  });

  let protocolClient = client;
  if (refusalOutcome.kind !== "grant") {
    protocolClient = new CommandTelemetryClient(config, "5".repeat(24));
    proof.recover(async () => { await protocolClient.close(); });
    await protocolClient.connect();
    console.log("OWNERSHIP_ENUMERATION_CASE_STEP owner-registration-protocol-controls replacement-client-connected");
  }
  const protocolError = new Promise((resolve) => protocolClient.once("transportError", resolve));
  protocolClient.write({ kind: "unknown-protocol-kind" });
  console.log("OWNERSHIP_ENUMERATION_CASE_STEP owner-registration-protocol-controls unknown-kind-dispatched");
  const error = await protocolError;
  console.log("OWNERSHIP_ENUMERATION_CASE_STEP owner-registration-protocol-controls unknown-kind-error");
  nativeObservation.protocolError = error.message;
  proof.mark("O:363", "unknown registered protocol kind fails the real connection", nativeObservation);
  assert.match(error.message, /COMMAND_TELEMETRY_PROTOCOL_VIOLATION/);
  return nativeObservation;
}

async function ownerAndClientAdditionalControls(evidenceRoot, proof) {
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-owner-client-additional",
  });
  const invocationId = "6a".repeat(12);
  const client = new CommandTelemetryClient(owner.configuration(), invocationId);
  let ownerClosed = false;
  proof.recover(async () => {
    await requireFulfilledRecovery([client.close()]);
    if (!ownerClosed) await owner.close();
  });
  await owner.start();
  const startObservation = {
    endpoint: owner.endpoint,
    commandRootExists: native.existsSync(owner.commandRoot),
    evidenceDirectoryExists: native.existsSync(owner.evidenceDirectory),
    serverListening: Boolean(owner.server?.listening),
  };
  proof.mark("O:39–40", "owner start selects one command-private Windows pipe endpoint", startObservation);
  proof.mark("O:146,204–206", "owner start creates and resolves its scratch command/evidence directories", startObservation);
  assert.match(owner.endpoint, /^\\\\\.\\pipe\\/);
  assert.equal(startObservation.serverListening, true);

  await client.connect();
  const connection = owner.invocations.get(invocationId)?.connection;
  const connectionObservation = {
    registered: client.registered,
    ownerConnections: owner.connections.size,
    invocationAllocated: owner.invocations.has(invocationId),
    socketDestroyed: client.socket?.destroyed,
  };
  proof.mark("O:256–269", "real accepted connection retains decoder and invocation ownership through native socket lifecycle", connectionObservation);
  proof.mark("O:1147–1154", "client retains its real socket, decoder and terminal failure lifecycle", connectionObservation);
  assert.ok(connection);
  assert.equal(connectionObservation.registered, true);

  let submissionSettled = false;
  let settleSubmission;
  const submissionSettlement = new Promise((resolve) => { settleSubmission = resolve; });
  const submitted = owner.write(connection, { kind: "grant", opId: "f".repeat(32), accepted: false }, () => {
    submissionSettled = true;
    settleSubmission();
  });
  const settledAtReturn = submissionSettled;
  await submissionSettlement;
  const submissionObservation = { submitted, settledAtReturn, settledAfterCallback: submissionSettled };
  proof.mark("O:326", "true reports native submission while callback settlement remains independently witnessed", submissionObservation);
  assert.equal(submitted, true);
  assert.equal(settledAtReturn, false);
  assert.equal(submissionSettled, true);

  let unsolicitedDispatch;
  const unsolicitedSeen = new Promise((resolve) => { unsolicitedDispatch = resolve; });
  const originalReceive = client.receive;
  client.receive = function observeUnsolicitedGrant(frame) {
    if (frame?.kind === "grant" && frame.opId === "e".repeat(32)) unsolicitedDispatch(frame);
    return originalReceive.call(this, frame);
  };
  const pendingBefore = client.pendingGrant.size;
  owner.write(connection, { kind: "grant", opId: "e".repeat(32), accepted: true, bytes: 1 });
  const unsolicited = await unsolicitedSeen;
  client.receive = originalReceive;
  const unsolicitedObservation = { accepted: unsolicited.accepted, pendingBefore, pendingAfter: client.pendingGrant.size };
  proof.mark("O:1209–1214", "unsolicited grant is received but cannot invent or settle an operation waiter", unsolicitedObservation);
  assert.equal(unsolicitedObservation.pendingAfter, pendingBefore);

  const listenerFailure = new Error("enumeration host listener failure");
  client.once("event", () => { throw listenerFailure; });
  let listenerThrow;
  try { client.receive({ kind: "host", event: { type: "counter_sample" }, channel: "counter" }); }
  catch (error) { listenerThrow = error; }
  const listenerObservation = { scope: "pure client callback propagation; no native lifecycle claim", message: listenerThrow?.message };
  proof.mark("O:1223", "host listener exception propagates without rewriting owner-committed evidence", listenerObservation);
  assert.equal(listenerThrow, listenerFailure);

  const originalSocketWrite = client.socket.write;
  client.socket.write = function callbackFailure(_bytes, callback) {
    callback?.(Object.assign(new Error("enumeration async client write callback failure"), { code: "EPIPE" }));
    return true;
  };
  let asyncWriteError;
  try { await client.writeAsync({ kind: "release", leaseId: "missing" }); }
  catch (error) { asyncWriteError = error; }
  client.socket.write = originalSocketWrite;
  const asyncWriteObservation = { scope: "native callback contract seam", message: asyncWriteError?.message };
  proof.mark("O:1186–1194", "async client write preserves its callback error as rejection", asyncWriteObservation);
  assert.match(asyncWriteError?.message ?? "", /callback failure/);

  const badConfig = { ...owner.configuration(), endpoint: `${owner.endpoint}-missing` };
  const failedClient = new CommandTelemetryClient(badConfig, "6b".repeat(12));
  const terminalWitness = new Promise((resolve) => failedClient.once("transportError", (error) => resolve(error.message)));
  const failedConnect = await failedClient.connect().then(
    () => ({ kind: "fulfilled" }),
    (error) => ({ kind: "rejected", message: error.message }),
  );
  const terminalMessage = await terminalWitness;
  await failedClient.close();
  const failedConnectObservation = {
    outcome: failedConnect,
    terminalMessage,
    socketDestroyed: failedClient.socket?.destroyed,
    registered: failedClient.registered,
  };
  proof.mark("O:1155–1160", "real connect failure cleans startup listeners and retains the terminal outcome", failedConnectObservation);
  assert.equal(failedConnect.kind, "rejected");
  assert.equal(failedClient.registered, false);

  const storedConnection = connection;
  const closeOrder = [];
  const clientTerminal = new Promise((resolve) => client.once("transportError", (error) => resolve(error.message)));
  const clientSocketClose = new Promise((resolve) => client.socket.once("close", () => { closeOrder.push("client-socket-close"); resolve(); }));
  const ownerSocketClose = new Promise((resolve) => storedConnection.socket.once("close", () => { closeOrder.push("owner-socket-close"); resolve(); }));
  const ownerClose = owner.close().then(() => { closeOrder.push("owner-close-resolved"); });
  ownerClosed = true;
  const terminalOnOwnerClose = await clientTerminal;
  await requireFulfilledRecovery([ownerClose, clientSocketClose, ownerSocketClose]);
  const afterCloseWrite = owner.write(storedConnection, { kind: "grant", opId: "d".repeat(32), accepted: false });
  const closeObservation = {
    terminalOnOwnerClose,
    closeOrder,
    nativeClientClosed: client.socket.destroyed,
    nativeOwnerSocketClosed: storedConnection.socket.destroyed,
    ownerConnectionsAfterNativeClose: owner.connections.size,
    afterCloseWrite,
  };
  proof.mark("O:302", "unwritable natively closed connection rejects a later owner write", closeObservation);
  proof.mark("O:1104", "accepted socket reaches both native close callbacks and owner connection settlement", closeObservation);
  assert.equal(closeObservation.nativeClientClosed, true);
  assert.equal(closeObservation.nativeOwnerSocketClosed, true);
  assert.equal(closeObservation.ownerConnectionsAfterNativeClose, 0);
  assert.equal(afterCloseWrite, false);
  return { startObservation, connectionObservation, submissionObservation, unsolicitedObservation, listenerObservation, asyncWriteObservation, failedConnectObservation, closeObservation };
}

async function ownerQueueAndClosedAdmissionControls(evidenceRoot, proof) {
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-owner-queue-closed",
  });
  const firstId = "7a".repeat(12);
  const secondId = "7b".repeat(12);
  const first = new CommandTelemetryClient(owner.configuration(), firstId);
  const second = new CommandTelemetryClient(owner.configuration(), secondId);
  let permission;
  let ownerClosed = false;
  proof.recover(async () => {
    if (permission) owner.abandonHostWork(permission);
    await requireFulfilledRecovery([first.close(), second.close()]);
    if (!ownerClosed) await owner.close();
  });
  await owner.start();
  await Promise.all([first.connect(), second.connect()]);
  permission = owner.reserveHostWork(firstId, "terminal", 200 * 1024);
  assert.ok(permission);
  let requestDispatched;
  const dispatched = new Promise((resolve) => { requestDispatched = resolve; });
  const originalRequest = owner.request;
  owner.request = function observeQueuedRequest(connection, frame) {
    const result = originalRequest.call(this, connection, frame);
    if (connection.invocationId === secondId) requestDispatched();
    return result;
  };
  const queuedRequest = second.requestWork("terminal", 64 * 1024).then(
    () => ({ kind: "fulfilled" }),
    (error) => ({ kind: "rejected", message: error.message }),
  );
  await dispatched;
  owner.request = originalRequest;
  const pendingBeforeClose = owner.accounting().pendingRequests;
  await second.close();
  const queuedOutcome = await queuedRequest;
  const pendingAfterClose = owner.accounting().pendingRequests;
  owner.abandonHostWork(permission);
  permission = undefined;
  owner.pumpRequests();
  const afterPump = owner.accounting();
  const queueObservation = { pendingBeforeClose, queuedOutcome, pendingAfterClose, outstandingAfterPump: afterPump.currentOutstandingBytes };
  proof.mark("O:383", "ineligible queued connection cannot receive a later grant", queueObservation);
  proof.mark("O:408", "stale queued reference is skipped only after its connection ownership changes", queueObservation);
  proof.mark("O:425–436", "connection close releases its queued request claim exactly once", queueObservation);
  assert.ok(pendingBeforeClose > 0);
  assert.equal(queuedOutcome.kind, "rejected");
  assert.equal(pendingAfterClose, 0);

  await first.close();
  await owner.close();
  ownerClosed = true;
  const closedClient = new CommandTelemetryClient(owner.configuration(), "7c".repeat(12));
  const closedOutcome = await closedClient.connect().then(
    () => ({ kind: "fulfilled" }),
    (error) => ({ kind: "rejected", message: error.message }),
  );
  await closedClient.close();
  const closedObservation = { closedOutcome, ownerClosed: owner.closed, pendingRequests: owner.accounting().pendingRequests };
  proof.mark("O:399", "closed owner admission cannot grant or queue new work", closedObservation);
  assert.equal(closedOutcome.kind, "rejected");
  return { queueObservation, closedObservation };
}

async function invocationSpecificFailedStageReconciliation(evidenceRoot, proof) {
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-invocation-reconcile",
  });
  const firstId = "8a".repeat(12);
  const secondId = "8b".repeat(12);
  let writeFault = true;
  let retainedSecond = true;
  const originalWriteFile = fs.writeFileSync;
  const originalRm = fs.rmSync;
  proof.recover(async () => {
    writeFault = false;
    retainedSecond = false;
    fs.writeFileSync = originalWriteFile;
    fs.rmSync = originalRm;
    syncFilesystemExports();
    owner.reconcileFailedStages(firstId);
    owner.reconcileFailedStages(secondId);
    await owner.close();
  });
  proof.safetyFallback(() => {
    for (const stage of owner.failedStages.values()) {
      for (const candidate of stage.possibleFiles ?? []) native.rmSync(candidate, { force: true });
    }
  });
  await owner.start();
  fs.writeFileSync = function partialStageWrite(file, data, ...args) {
    if (writeFault && samePath(path.dirname(file), owner.evidenceDirectory)) {
      native.writeFileSync(file, Buffer.from(data).subarray(0, Math.min(7, Buffer.byteLength(data))), ...args);
      throw new Error("enumeration invocation-specific partial stage");
    }
    return originalWriteFile.call(this, file, data, ...args);
  };
  fs.rmSync = function retainedStageRemoval(file, ...args) {
    if (samePath(path.dirname(String(file)), owner.evidenceDirectory) && String(file).includes(".terminal.")) return undefined;
    return originalRm.call(this, file, ...args);
  };
  syncFilesystemExports();
  for (const invocationId of [firstId, secondId]) {
    assert.throws(() => owner.commitHostEvidence(invocationId, {
      type: "invocation_terminal", outcome: "succeeded", marker: invocationId,
    }), /partial stage/);
  }
  const before = [...owner.failedStages.values()].map((stage) => ({ invocationId: stage.invocationId, possibleFiles: [...stage.possibleFiles] }));
  writeFault = false;
  const secondFiles = new Set(before.filter((stage) => stage.invocationId === secondId).flatMap((stage) => stage.possibleFiles).map((file) => path.resolve(file)));
  const scopedRemovalAttempts = [];
  fs.rmSync = function selectiveRecovery(file, ...args) {
    const resolved = path.resolve(String(file));
    scopedRemovalAttempts.push({ file: resolved, invocationId: secondFiles.has(resolved) ? secondId : firstId });
    if (retainedSecond && secondFiles.has(resolved)) return undefined;
    return originalRm.call(this, file, ...args);
  };
  syncFilesystemExports();
  owner.reconcileFailedStages(firstId);
  const afterFirst = [...owner.failedStages.values()].map((stage) => stage.invocationId);
  const observation = {
    before, afterFirst, scopedRemovalAttempts,
    firstRetained: afterFirst.includes(firstId), secondRetained: afterFirst.includes(secondId),
    secondRemovalAttempted: scopedRemovalAttempts.some((attempt) => attempt.invocationId === secondId),
  };
  proof.mark("O:522", "invocation-scoped reconciliation attempts only the selected invocation's actual stage paths", observation);
  assert.equal(observation.firstRetained, false);
  assert.equal(observation.secondRetained, true);
  assert.equal(observation.secondRemovalAttempted, false,
    "a still-faulted second stage must not be touched while reconciling the first invocation");
  return observation;
}

async function ownerPayloadValidationControls(evidenceRoot, proof) {
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-payload-validation",
  });
  const clients = [];
  proof.recover(async () => {
    await requireFulfilledRecovery(clients.map((client) => client.close()));
    await owner.close();
  });
  await owner.start();
  const runFault = async (suffix, send, expected) => {
    const client = new CommandTelemetryClient(owner.configuration(), suffix.repeat(24));
    clients.push(client);
    await client.connect();
    const grant = await client.requestWork("terminal", 4096);
    const transportError = new Promise((resolve) => client.once("transportError", resolve));
    send(client, grant);
    const error = await transportError;
    assert.match(error.message, expected);
    await client.close();
    return { message: error.message, outstanding: owner.accounting().currentOutstandingBytes };
  };
  const mismatched = await runFault("a", (client, grant) => {
    client.write({ kind: "payload", opId: "0".repeat(32), channel: grant.channel, event: { type: "wrong-op" } });
  }, /UNADMITTED_PAYLOAD/);
  const invalidBase64 = await runFault("b", (client, grant) => {
    client.write({ kind: "payload_chunk", opId: grant.opId, channel: grant.channel, data: "***", final: false });
  }, /PAYLOAD_EXCEEDS_GRANT/);
  const malformedFinal = await runFault("c", (client, grant) => {
    client.write({ kind: "payload_chunk", opId: grant.opId, channel: grant.channel, data: Buffer.from("{bad").toString("base64"), final: true });
  }, /CHUNKED_PAYLOAD_INVALID/);

  const partialClient = new CommandTelemetryClient(owner.configuration(), "d".repeat(24));
  clients.push(partialClient);
  await partialClient.connect();
  const partialGrant = await partialClient.requestWork("terminal", 4096);
  const originalReceive = owner.receive;
  let partialResolve;
  const partialDispatched = new Promise((resolve) => { partialResolve = resolve; });
  owner.receive = function observePartial(connection, frame) {
    const result = originalReceive.call(this, connection, frame);
    if (connection.invocationId === partialClient.invocationId && frame?.kind === "payload_chunk") partialResolve();
    return result;
  };
  partialClient.write({
    kind: "payload_chunk", opId: partialGrant.opId, channel: partialGrant.channel,
    data: Buffer.from('{"type":"partial"').toString("base64"), final: false,
  });
  await partialDispatched;
  const pending = owner.invocations.get(partialClient.invocationId).connection.pending;
  const partialObservation = {
    status: pending.status,
    receivedBytes: pending.receivedBytes,
    outstandingBytes: owner.accounting().currentOutstandingBytes,
  };
  owner.receive = originalReceive;
  await partialClient.close();
  const nativeObservation = { mismatched, invalidBase64, malformedFinal, partialObservation };
  proof.mark("O:564–569", "whole payload requires exact admitted operation/channel identity", nativeObservation);
  proof.mark("O:574–580", "chunk payload requires canonical bounded base64 and matching grant", nativeObservation);
  proof.mark("O:582–584", "nonfinal chunk remains owned in the granted operation", nativeObservation);
  proof.mark("O:586–590", "malformed final chunk fails transport instead of publication", nativeObservation);
  assert.equal(partialObservation.status, "granted");
  assert.ok(partialObservation.outstandingBytes > 0);
  return nativeObservation;
}

function committedReaderReplacementBeforeOpen(evidenceRoot, proof) {
  const invocationId = "9a9a9a9a9a9a9a9a9a9a9a9a";
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-committed-replacement",
  });
  assert.equal(owner.commitHostEvidence(invocationId, { type: "invocation_terminal", marker: "COMMITTED_ORIGINAL" }), true);
  const current = owner.generations.get(invocationId);
  const delivery = owner.retainCommittedDelivery(invocationId, current.generation);
  let actualReadBytes = 0;
  let replaced = false;
  const originalOpen = fs.openSync;
  const originalRead = fs.readSync;
  fs.openSync = function replaceBeforeOpen(candidate, ...args) {
    if (!replaced && samePath(candidate, current.file)) {
      replaced = true;
      const replacement = `${current.file}.replacement`;
      native.writeFileSync(replacement, Buffer.alloc(current.bytes, 88));
      native.renameSync(replacement, current.file);
    }
    return originalOpen.call(this, candidate, ...args);
  };
  fs.readSync = function measuredRead(...args) { const bytes = originalRead.apply(this, args); actualReadBytes += bytes; return bytes; };
  let thrown;
  try { owner.readCommittedDelivery(delivery); } catch (error) { thrown = error; }
  fs.openSync = originalOpen;
  fs.readSync = originalRead;
  owner.releaseReader(delivery.leaseId);
  const nativeObservation = { thrown: thrown?.message, actualReadBytes, replaced };
  proof.mark("O:790–795", "committed reader rejects same-size pathname replacement before evidence read", nativeObservation);
  assert.match(thrown?.message ?? "", /COMMITTED_(?:IDENTITY|HANDLE)_CHANGED/);
  assert.equal(actualReadBytes, 0);
  return nativeObservation;
}

async function ownerGrantWriteFailureReleasesUnspentWork(evidenceRoot, proof) {
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-grant-write-failure",
  });
  const invocationId = "9d".repeat(12);
  const client = new CommandTelemetryClient(owner.configuration(), invocationId);
  let connection;
  let originalSocketWrite;
  proof.recover(async () => {
    if (connection && originalSocketWrite) connection.socket.write = originalSocketWrite;
    await requireFulfilledRecovery([client.close(), owner.close()]);
  });
  await owner.start();
  await client.connect();
  connection = owner.invocations.get(invocationId).connection;
  originalSocketWrite = connection.socket.write;
  let nativeSocketClosed = false;
  const nativeSocketClose = new Promise(resolve => connection.socket.once("close", () => {
    nativeSocketClosed = true; resolve();
  }));
  let grantFaultHit = 0;
  connection.socket.write = function failAcceptedGrant(bytes, ...args) {
    const frame = JSON.parse(Buffer.from(bytes).toString("utf8").trim());
    if (frame.kind === "grant" && frame.accepted === true && typeof frame.opId === "string") {
      grantFaultHit += 1;
      throw new Error("enumeration grant native write failure");
    }
    return originalSocketWrite.call(this, bytes, ...args);
  };
  let requestError;
  try { await client.requestWork("ordinary", 1024); } catch (error) { requestError = error; }
  await nativeSocketClose;
  const nativeObservation = {
    requestError: requestError?.message,
    nativeSocketClosed,
    grantFaultHit,
    pendingRequests: owner.accounting().pendingRequests,
    outstandingBytes: owner.accounting().currentOutstandingBytes,
    reservedQueueBytes: owner.accounting().reservedEventQueueBytes,
  };
  proof.mark("O:417–418", "failed grant submission releases only unspent grant and settles connection", nativeObservation);
  assert.equal(grantFaultHit,1,"fault must intercept the real accepted grant including its opId");
  assert.equal(requestError?.message,"COMMAND_TELEMETRY_OWNER_CLOSED",
    "the native grant write error is translated to terminal client transport closure");
  assert.equal(nativeSocketClosed,true,"the accepted grant's real native socket must close");
  assert.deepEqual({ pending: nativeObservation.pendingRequests, outstanding: nativeObservation.outstandingBytes, reserved: nativeObservation.reservedQueueBytes },
    { pending: 0, outstanding: 0, reserved: 0 });
  return nativeObservation;
}

