async function ownerFailedStartIsNotReady(evidenceRoot, proof) {
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-owner-start",
  });
  const originalCreateServer = net.createServer;
  let created;
  let injected = true;
  net.createServer = function createFailedServer(...args) {
    const server = originalCreateServer.apply(this, args);
    created = server;
    const originalListen = server.listen;
    server.listen = function failedListen() {
      if (!injected) return originalListen.apply(this, arguments);
      queueMicrotask(() => server.emit("error", Object.assign(new Error("enumeration listen failure"), { code: "EACCES" })));
      return server;
    };
    return server;
  };
  proof.recover(async () => {
    injected = false;
    net.createServer = originalCreateServer;
    await owner.close();
  });
  let first;
  try { await owner.start(); } catch (error) { first = error; }
  injected = false;
  let second;
  try { await owner.start(); } catch (error) { second = error; }
  const nativeObservation = {
    first: first?.message,
    second: second?.message,
    serverRetained: owner.server === created,
    listening: Boolean(owner.server?.listening),
  };
  for (const site of ["O:210", "O:212–224"]) {
    proof.mark(site, "failed owner listen is shared as failure rather than inferred ready from server existence", nativeObservation);
  }
  assert.equal(second instanceof Error, true, "a second start cannot fulfill while the retained server never became ready");
  return nativeObservation;
}

async function clientConcurrentConnectSharesRegistration(evidenceRoot, proof) {
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-client-connect",
  });
  const invocationId = "a2".repeat(12);
  const client = new CommandTelemetryClient(owner.configuration(), invocationId);
  const originalReceive = owner.receive;
  let held;
  let releaseDispatch;
  const registrationArrived = new Promise((resolve) => { releaseDispatch = resolve; });
  owner.receive = function holdRegistration(connection, frame) {
    if (!connection.registered && frame?.kind === "register") {
      held = { connection, frame };
      releaseDispatch();
      return;
    }
    return originalReceive.call(this, connection, frame);
  };
  let first;
  proof.recover(async () => {
    owner.receive = originalReceive;
    if (held && !client.registered && !client.closed) originalReceive.call(owner, held.connection, held.frame);
    if (first) await requireFulfilledRecovery([first]);
    await requireFulfilledRecovery([client.close(), owner.close()]);
  });
  await owner.start();
  first = client.connect();
  await registrationArrived;
  const second = client.connect();
  const nativeObservation = {
    socketEstablished: Boolean(client.socket),
    registrationHeld: Boolean(held),
    registeredWhileHeld: client.registered,
    sharesRegistrationPromise: second === first,
  };
  proof.mark("O:1146", "concurrent connect awaits the shared registration outcome", nativeObservation);
  try {
    assert.equal(second, first,
      "a second connect must join the unsettled first registration, not the established socket alone");
    assert.equal(client.registered, false, "the registration is still held at this native dispatch barrier");
  } finally {
    if (held) originalReceive.call(owner, held.connection, held.frame);
    await requireFulfilledRecovery([first, second]);
  }
  return nativeObservation;
}

