async function multiWriteThrowRetainsEarlierCallback(evidenceRoot, proof) {
  const owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-multi-write",
  });
  const invocationId = "c2".repeat(12);
  const client = new CommandTelemetryClient(owner.configuration(), invocationId);
  let connection;
  let originalWrite;
  let held;
  let writes = 0;
  let permission;
  proof.recover(async () => {
    if (connection && originalWrite) connection.socket.write = originalWrite;
    if (held && !held.forwarded) { held.forwarded = true; held.callback(held.error); }
    if (permission && owner.hostPermissions.has(permission.permissionId)) owner.abandonHostWork(permission);
    await requireFulfilledRecovery([client.close(), owner.close()]);
  });
  await owner.start();
  await client.connect();
  connection = owner.invocations.get(invocationId).connection;
  originalWrite = connection.socket.write;
  let firstCallbackResolve;
  const firstCallbackArrived = new Promise((resolve) => { firstCallbackResolve = resolve; });
  connection.socket.write = function writeThenThrow(bytes, callback) {
    writes += 1;
    if (writes === 2) throw new Error("enumeration second native write throw");
    return originalWrite.call(this, bytes, (error) => {
      held = { callback: callback ?? (() => {}), error, forwarded: false };
      firstCallbackResolve();
    });
  };
  permission = owner.reserveHostWork(invocationId, "counter", 16 * 1024);
  const firstEvent = new Promise((resolve) => client.once("event", resolve));
  assert.equal(owner.sendToInvocation(invocationId, { type: "counter_sample", sequence: 1 }, "counter", permission), true);
  await Promise.all([firstEvent, firstCallbackArrived]);
  assert.equal(owner.sendToInvocation(invocationId, { type: "counter_sample", sequence: 2 }, "counter", permission), false);
  owner.completeHostWork(permission, 1);
  const admitted = owner.hostPermissions.get(permission.permissionId);
  const nativeObservation = {
    actualWrites: writes,
    earlierCallbackForwarded: held.forwarded,
    permissionRetained: owner.hostPermissions.has(permission.permissionId),
    pendingWrites: admitted?.pendingWrites,
    outstandingBytes: owner.accounting().currentOutstandingBytes,
  };
  proof.mark("O:955–958", "synchronous failure of a later write cannot decrement the earlier native callback", nativeObservation);
  assert.equal(nativeObservation.permissionRetained, true,
    "the earlier real native write remains owned until its own callback is forwarded exactly once");
  assert.equal(nativeObservation.pendingWrites, 1);
  return nativeObservation;
}

