function publicationHookAndAdmissionControls(evidenceRoot, proof) {
  const invocationId = "9e".repeat(12);
  let owner;
  let mode = "healthy";
  let preparedObservation;
  let committedHookCalls = 0;
  owner = new CommandTelemetryOwner({
    commandRoot: path.join(evidenceRoot, "command"), evidenceDirectory: path.join(evidenceRoot, "evidence"),
    commandId: "enumeration-publication-hooks",
    publicationHook(info) {
      if (info.phase === "prepared" && mode === "prepared-failure") {
        const originalStat = fs.statSync;
        fs.statSync = function activeStageStatFailure(candidate, ...args) {
          if (samePath(candidate, info.temporary)) throw denied("enumeration active stage stat failure");
          return originalStat.call(this, candidate, ...args);
        };
        preparedObservation = {
          accounting: owner.accounting(),
          stageExists: native.existsSync(info.temporary),
        };
        fs.statSync = originalStat;
        throw new Error("enumeration prepared hook failure");
      }
      if (info.phase === "committed" && mode === "committed-failure") {
        committedHookCalls += 1;
        throw new Error("enumeration committed hook failure");
      }
    },
  });
  assert.equal(owner.commitHostEvidence(invocationId, { type: "invocation_terminal", marker: "HOOK_PRIOR" }), true);
  const prior = owner.acquireCommitted(invocationId);
  mode = "prepared-failure";
  assert.throws(() => owner.commitHostEvidence(invocationId, { type: "invocation_terminal", marker: "PREPARED_FAIL" }), /prepared hook failure/);
  assert.ok(preparedObservation.accounting.activeStages >= 1);
  assert.ok(preparedObservation.accounting.currentOutstandingBytes > 0);
  assert.match(prior.bytes.toString("utf8"), /HOOK_PRIOR/);
  owner.releaseReader(prior.leaseId);
  mode = "committed-failure";
  assert.equal(owner.commitHostEvidence(invocationId, { type: "invocation_terminal", marker: "COMMITTED_SURVIVES_HOOK" }), true);
  const committed = owner.acquireCommitted(invocationId);
  assert.match(committed.bytes.toString("utf8"), /COMMITTED_SURVIVES_HOOK/);
  owner.releaseReader(committed.leaseId);
  assert.throws(() => owner.commitEvidence(invocationId, { type: "invocation_terminal" }, 1, 1), /TERMINAL_EXCEEDS_BOUND/);
  const nativeObservation = { preparedObservation, committedHookCalls, currentDigest: owner.generations.get(invocationId).sha256 };
  for (const site of ["O:544–547", "O:649", "O:653", "O:671–675", "O:726"]) {
    proof.mark(site, "publication stage/hook/admission ownership control", nativeObservation);
  }
  return nativeObservation;
}

