  assert.equal(nativeObservation.pending,true,"a failed metadata observation cannot consume a pending ACK");
  proof.mark("M:1159", "ACK metadata EACCES is explicit unavailable observation rather than ordinary absence", nativeObservation);
  assert.equal(result?.kind, "unavailable",
    "inaccessible ACK metadata cannot be indistinguishable from an absent receipt");
