function supervisorLegacyBudgetAndSchedulerControls(evidenceRoot, proof) {
  const budget = new supervisor.SharedReadBudget(16);
  budget.beginCycle();
  assert.equal(budget.reserveBeforeRead(16, "legacy"), 16);
  assert.equal(budget.reserveBeforeRead(1, "exhausted"), 0);
  budget.consumeActual(16, "legacy");
  assert.throws(() => budget.consumeActual(1, "overflow"), /ACTUAL_READ_EXCEEDED_RESERVED_CREDITS/);
  const scheduler = new supervisor.CounterSamplingScheduler(10);
  scheduler.requestFresh();
  const generation = scheduler.tick(0, true);
  assert.equal(scheduler.tick(1, true), undefined);
  assert.equal(scheduler.acceptResponse(generation + 1), false);
  assert.equal(scheduler.acceptResponse(generation), true);
  scheduler.fail();
  const nativeObservation = { budget: budget.accounting(), generation };
  for (const site of ["S:94–99", "S:102–104", "S:119–130"]) {
    proof.mark(site, "legacy bounded read and counter scheduling preservation controls", nativeObservation);
  }
  return nativeObservation;
}

