function supervisorPolicyAndAuthorityControls(evidenceRoot, proof) {
  const policy = { minimumObservationMs: 20, alarmAfterMs: 45, cancelAfterMs: 90, minimumAlarmLeadMs: 20, pollMs: 5 };
  const machine = new supervisor.SilencePolicyMachine(policy, 0);
  const decisions = [machine.tick(19), machine.tick(44), machine.tick(100), machine.tick(119)];
  machine.observeOutput(120);
  decisions.push(machine.tick(200));
  const acknowledged = machine.acknowledgeAlarm(200);
  decisions.push(machine.tick(220));
  machine.finalize();
  const afterFinal = machine.tick(300);

  const workspace = path.join(evidenceRoot, "workspace");
  fs.mkdirSync(workspace, { recursive: true });
  const script = path.join(workspace, "authorized.cjs");
  const preload = path.join(workspace, "preload.cjs");
  fs.writeFileSync(script, "console.log('AUTHORIZED');\n");
  fs.writeFileSync(preload, "// frozen preload\n");
  const frozen = (file) => {
    const bytes = fs.readFileSync(file);
    return { path: fs.realpathSync(file), bytes: bytes.length, sha256: sha256(bytes) };
  };
  const authorization = {
    workspaceRealPath: fs.realpathSync(workspace),
    existingEntrypoints: [frozen(script), frozen(preload)],
    approvedDynamicScopes: [],
    allowedNodeOptions: ["--require"],
  };
  const eligible = supervisor.classifyTest([script], workspace, authorization);
  const missingAuthority = supervisor.classifyTest([script], workspace, undefined);
  const withPreload = supervisor.classifyTest(["--require", preload, script], workspace, authorization);
  fs.writeFileSync(script, "console.log('CHANGED');\n");
  const changed = supervisor.classifyTest([script], workspace, authorization);
  const unsafeDirectory = supervisor.classifyTest([workspace], workspace, authorization);
  const nativeObservation = {
    decisions: decisions.map((decision) => decision?.kind ?? null),
    acknowledged,
    afterFinal,
    eligible: eligible.eligible,
    missingAuthority: missingAuthority.eligible,
    withPreload: withPreload.eligible,
    changed: changed.eligible,
    unsafeDirectory: { eligible: unsafeDirectory.eligible, reason: unsafeDirectory.reason },
  };
  for (const site of [
    "S:24–31", "S:45,52", "S:54–58", "S:61–63", "S:66–83", "S:85",
    "S:256", "S:298–321", "S:323–333", "S:337–341", "S:342–345", "S:347–355", "S:364–368",
  ]) proof.mark(site, "supervisor policy and frozen authority preservation control", nativeObservation);
  assert.deepEqual(nativeObservation.decisions, [null, null, "alarm", null, "alarm", "cancel"]);
  assert.equal(acknowledged, true);
  assert.equal(afterFinal, undefined);
  assert.deepEqual({ eligible: eligible.eligible, missing: missingAuthority.eligible, preload: withPreload.eligible, changed: changed.eligible },
    { eligible: true, missing: false, preload: true, changed: false });
  assert.deepEqual(nativeObservation.unsafeDirectory, { eligible: false, reason: "entrypoint identity is unsafe" });
  return nativeObservation;
}

function ownerlessReaderCloseFailureIsNotSettled(evidenceRoot, proof) {
  const target = path.join(evidenceRoot, "ownerless.bin");
  fs.writeFileSync(target, "OWNERLESS_READER");
  const budget = new monitor.SharedReadBudget(256 * 1024);
  const reader = new monitor.EventReader(evidenceRoot, budget);
  const descriptors = new Set();
  let rejectClose = true;
  fs.openSync = function trackedOpen(candidate, ...args) {
    const descriptor = native.openSync.call(this, candidate, ...args);
    if (samePath(candidate, target)) descriptors.add(descriptor);
    return descriptor;
  };
  fs.closeSync = function failedOwnerlessClose(descriptor, ...args) {
    if (rejectClose && descriptors.has(descriptor)) throw Object.assign(new Error("enumeration ownerless close failure"), { code: "EIO" });
    const result = native.closeSync.call(this, descriptor, ...args);
    descriptors.delete(descriptor);
    return result;
  };
  syncFilesystemExports();
  const faultMonitor = loadFreshMonitor(evidenceRoot, "ownerless-reader-fault");
  proof.recover(() => {
    rejectClose = false;
    const recoveryBudget = new faultMonitor.SharedReadBudget(256 * 1024);
    const recoveryReader = new faultMonitor.EventReader(evidenceRoot, recoveryBudget);
    recoveryBudget.beginCycle();
    recoveryReader.readFileWithinCycleOutcome(target, 256 * 1024, "ownerless-recovery", evidenceRoot);
    recoveryBudget.finalizeCycle();
    assert.equal([...descriptors].filter(descriptorOpen).length, 0,
      "public ownerless reader recovery must settle the previously open descriptor");
  });
  proof.safetyFallback(() => {
    for (const descriptor of descriptors) if (descriptorOpen(descriptor)) native.closeSync(descriptor);
  });
  const faultBudget = new faultMonitor.SharedReadBudget(256 * 1024);
  const faultReader = new faultMonitor.EventReader(evidenceRoot, faultBudget);
  faultBudget.beginCycle();
  const outcome = faultReader.readFileWithinCycleOutcome(target, 256 * 1024, "ownerless-failure", evidenceRoot);
  faultBudget.finalizeCycle();
  const nativeObservation = { outcome: outcome.kind, openDescriptors: [...descriptors].filter(descriptorOpen) };
  proof.mark("M:248", "ownerless exported reader does not lose an inconclusively closed descriptor", nativeObservation);
  proof.mark("M:289", "ownerless cycle finalization cannot report settled while descriptor remains open", nativeObservation);
  assert.equal(nativeObservation.openDescriptors.length, 0,
    "standalone exported reader must not return after losing ownership of a real open descriptor");
  return nativeObservation;
}

function eventSealCloseFailureIsUnavailable(evidenceRoot, proof) {
  const { directory, owner, budget, reader } = createEventHarness(evidenceRoot, "enumeration-event-seal-close");
  const source = path.join(directory, `${"95".repeat(12)}.events.1.jsonl`);
  const line = `${JSON.stringify({ type: "event", marker: "SEAL_CLOSE" })}\n`;
  const seal = `${source}.sealed`;
  fs.writeFileSync(source, line);
  fs.writeFileSync(seal, String(Buffer.byteLength(line)));
  const descriptors = new Set();
  let rejectClose = true;
  fs.openSync = function trackedSealOpen(candidate, ...args) {
    const descriptor = native.openSync.call(this, candidate, ...args);
    if (samePath(candidate, seal)) descriptors.add(descriptor);
    return descriptor;
  };
  fs.closeSync = function failedSealClose(descriptor, ...args) {
    if (rejectClose && descriptors.has(descriptor)) throw Object.assign(new Error("enumeration seal close failure"), { code: "EIO" });
    const result = native.closeSync.call(this, descriptor, ...args);
    descriptors.delete(descriptor);
    return result;
  };
  syncFilesystemExports();
  const faultMonitor = loadFreshMonitor(evidenceRoot, "event-seal-close-fault");
  const faultBudget = new faultMonitor.SharedReadBudget(256 * 1024, owner);
  const faultReader = new faultMonitor.EventReader(directory, faultBudget);
  proof.recover(() => {
    rejectClose = false;
    owner.advanceCycle(); faultBudget.beginCycle();
    faultReader.poll();
    faultBudget.finalizeCycle();
    assert.equal([...descriptors].filter(descriptorOpen).length, 0);
    assert.equal(owner.accounting().retainedReaderDescriptors, 0);
  });
  proof.safetyFallback(() => {
    for (const descriptor of descriptors) if (descriptorOpen(descriptor)) native.closeSync(descriptor);
  });
  faultBudget.beginCycle();
  const events = faultReader.poll();
  faultBudget.finalizeCycle();
  const nativeObservation = {
    markers: events.map((event) => event.marker),
    sourceExists: native.existsSync(source),
    sealExists: native.existsSync(seal),
    hasPending: faultReader.hasPending(),
    openDescriptors: [...descriptors].filter(descriptorOpen),
    ownerRetainedDescriptors: owner.accounting().retainedReaderDescriptors,
  };
  for (const site of ["M:403–405", "M:459", "M:473–474"]) {
    proof.mark(site, "admitted seal close failure is unavailable, not credit deferral", nativeObservation);
  }
  assert.equal(nativeObservation.hasPending, false,
    "admitted seal close failure retains ownership without spinning final drain");
  assert.equal(events.some((event) => event.type === "observation_error"), true,
    "admitted seal close failure must report unavailable evidence once");
  assert.ok(nativeObservation.openDescriptors.length > 0);
  assert.ok(nativeObservation.ownerRetainedDescriptors > 0);
  return nativeObservation;
}

function legacyCaptureMetadataUnknown(evidenceRoot, proof) {
  const workspace = path.join(evidenceRoot, "workspace");
  const target = path.join(workspace, "capture.log");
  fs.mkdirSync(workspace, { recursive: true });
  fs.writeFileSync(target, "LEGACY_CAPTURE");
  const parent = fs.lstatSync(workspace, { bigint: true });
  const spec = { path: target, parentRealPath: fs.realpathSync(workspace), parentDevice: parent.dev.toString(), parentInode: parent.ino.toString() };
  const readBudget = new supervisor.SharedReadBudget();
  readBudget.beginCycle();
  fs.existsSync = function falseExistence(candidate) {
    if (samePath(candidate, target)) return false;
    return native.existsSync.call(this, candidate);
  };
  syncFilesystemExports();
  const result = supervisor.captureDeclaredFilesAfterSettlement([spec], fs.realpathSync(workspace), 64 * 1024, readBudget);
  const nativeObservation = { actualExists: native.existsSync(target), reported: result.results[0] };
  proof.mark("S:401", "legacy capture does not convert inaccessible existence to missing", nativeObservation);
  assert.equal(result.results[0].status, "unavailable");
  return nativeObservation;
}

function legacyCaptureCloseFailureIsOwned(evidenceRoot, proof) {
  const workspace = path.join(evidenceRoot, "workspace");
  const target = path.join(workspace, "capture.log");
  fs.mkdirSync(workspace, { recursive: true });
  fs.writeFileSync(target, "LEGACY_CLOSE_FAILURE");
  const parent = fs.lstatSync(workspace, { bigint: true });
  const spec = { path: target, parentRealPath: fs.realpathSync(workspace), parentDevice: parent.dev.toString(), parentInode: parent.ino.toString() };
  const descriptors = new Set();
  let rejectClose = true;
  fs.openSync = function trackedOpen(candidate, ...args) {
    const descriptor = native.openSync.call(this, candidate, ...args);
    if (samePath(candidate, target)) descriptors.add(descriptor);
    return descriptor;
  };
  fs.closeSync = function unresolvedClose(descriptor, ...args) {
    if (rejectClose && descriptors.has(descriptor)) throw Object.assign(new Error("enumeration legacy close failure"), { code: "EIO" });
    const result = native.closeSync.call(this, descriptor, ...args);
    descriptors.delete(descriptor);
    return result;
  };
  syncFilesystemExports();
  proof.recover(() => {
    rejectClose = false;
    fs.openSync = native.openSync;
    fs.closeSync = native.closeSync;
    const recoveredBudget = new supervisor.SharedReadBudget();
    recoveredBudget.beginCycle();
    supervisor.captureDeclaredFilesAfterSettlement([spec], fs.realpathSync(workspace), 64 * 1024, recoveredBudget);
    assert.equal([...descriptors].filter(descriptorOpen).length, 0,
      "public legacy capture recovery must settle its previously retained descriptor");
  });
  proof.safetyFallback(() => {
    for (const descriptor of descriptors) if (descriptorOpen(descriptor)) native.closeSync(descriptor);
  });
  const readBudget = new supervisor.SharedReadBudget();
  readBudget.beginCycle();
  let thrown;
  try { supervisor.captureDeclaredFilesAfterSettlement([spec], fs.realpathSync(workspace), 64 * 1024, readBudget); }
  catch (error) { thrown = error; }
  const nativeObservation = {
    thrown: thrown?.message,
    openDescriptors: [...descriptors].filter(descriptorOpen),
  };
  proof.mark("S:451–457", "legacy capture retains an actual descriptor after inconclusive close", nativeObservation);
  assert.equal(nativeObservation.openDescriptors.length, 0,
    "legacy capture must not return or throw while leaving its native descriptor ownerless");
  return nativeObservation;
}

async function runPreloadFixture(evidenceRoot, { configText, patchSource = "", bodySource = "console.log('PRELOAD_BODY_COMPLETE');" }) {
  fs.mkdirSync(evidenceRoot, { recursive: true });
  const patchFile = path.join(evidenceRoot, "preload-patch.cjs");
  const bodyFile = path.join(evidenceRoot, "preload-body.cjs");
  fs.writeFileSync(patchFile, patchSource || "// no patch\n");
  fs.writeFileSync(bodyFile, `${bodySource}\n`);
  const child = spawn(process.execPath, [
    "--require", patchFile,
    "--require", path.join(ROOT, "src", "no-output-io-observer.cjs"),
    bodyFile,
  ], {
    cwd: evidenceRoot,
    env: { ...process.env, PI_ORC_IO_OBSERVER: "1", PI_OFFLINE: "1" },
    stdio: ["ignore", "pipe", "pipe", "pipe", "pipe"],
    windowsHide: true,
    detached: false,
  });
  let stdout = "";
  let stderr = "";
  let control = "";
  child.stdout.on("data", (chunk) => { stdout += chunk; });
  child.stderr.on("data", (chunk) => { stderr += chunk; });
  child.stdio[3].on("data", (chunk) => { control += chunk; });
  child.stdio[4].end(configText ?? "");
  const settlement = await new Promise((resolve, reject) => {
    child.once("error", reject);
    child.once("close", (code, signal) => resolve({ code, signal }));
  });
  return { ...settlement, stdout, stderr, control };
}

async function preloadBootstrapClassification(evidenceRoot, proof) {
  const validConfig = JSON.stringify({ ownerConfiguration: { ownerId: "private-owner" }, marker: "CONFIG_DIGEST_ONLY" });
  const valid = await runPreloadFixture(path.join(evidenceRoot, "valid"), { configText: validConfig });
  const invalid = await runPreloadFixture(path.join(evidenceRoot, "invalid"), { configText: "{invalid-json" });
  const empty = await runPreloadFixture(path.join(evidenceRoot, "empty"), { configText: "" });
  const decode = (text) => text.trim().split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
  const nativeObservation = {
    validExit: valid.code,
    invalidExit: invalid.code,
    emptyExit: empty.code,
    validFrames: decode(valid.control),
    invalidFrames: decode(invalid.control),
    emptyFrames: decode(empty.control),
    validConfigSha256: sha256(Buffer.from(validConfig)),
  };
  for (const site of ["I:8", "I:15–17", "I:19", "I:24"]) {
    proof.mark(site, "actual preload bootstrap distinguishes configuration and transport readiness without changing child exit", nativeObservation);
  }
  assert.equal(nativeObservation.validFrames[0].transportReady, true);
  assert.equal(nativeObservation.invalidFrames[0].transportReady, false);
  assert.notEqual(nativeObservation.invalidFrames[0].bootstrapStatus, nativeObservation.emptyFrames[0].bootstrapStatus,
    "invalid/failed configuration must remain distinguishable from genuinely absent optional transport");
  return nativeObservation;
}

async function preloadShortWriteIsExplicit(evidenceRoot, proof) {
  const patchSource = [
    "const fs = require('node:fs');",
    "const original = fs.writeSync;",
    "fs.writeSync = function(fd, value, ...args) {",
    "  if (fd === 3) { const text = String(value); return original.call(this, fd, text.slice(0, Math.max(0, text.length - 1))); }",
    "  return original.call(this, fd, value, ...args);",
    "};",
    "",
  ].join("\n");
  const result = await runPreloadFixture(evidenceRoot, {
    configText: JSON.stringify({ marker: "SHORT_WRITE_CONFIG" }),
    patchSource,
  });
  let parsed;
  try { parsed = JSON.parse(result.control.trim()); } catch {}
  const nativeObservation = {
    exitCode: result.code,
    bodyCompleted: /PRELOAD_BODY_COMPLETE/.test(result.stdout),
    actualControlBytes: Buffer.byteLength(result.control),
    completeFrameParsed: Boolean(parsed),
    controlTail: result.control.slice(-32),
  };
  proof.mark("I:20–21", "short actual FD3 write is classified as failed emission while preserving child behavior", nativeObservation);
  assert.match(result.control, /transport_write_failed/,
    "a short control write must be reported as failed rather than counted as an emitted frame");
  return nativeObservation;
}

async function preloadUnsupportedApiControls(evidenceRoot, proof) {
  const bodySource = [
    "const fs = require('node:fs');",
    "const path = require('node:path');",
    "const cp = require('node:child_process');",
    "const childFile = path.join(__dirname, 'fork-child.cjs');",
    "fs.writeFileSync(childFile, \"console.log('FORK_CHILD_COMPLETE');\\n\");",
    "cp.spawnSync(process.execPath, ['-e', \"console.log('SPAWN_SYNC_COMPLETE')\"], { stdio: 'ignore' });",
    "cp.execSync(`\"${process.execPath}\" -e \"\"`);",
    "cp.execFileSync(process.execPath, ['-e', '']);",
    "Promise.all([",
    "  new Promise((resolve) => cp.exec(`\"${process.execPath}\" -e \"\"`, () => resolve())),",
    "  new Promise((resolve) => cp.execFile(process.execPath, ['-e', ''], () => resolve())),",
    "  new Promise((resolve, reject) => { const child = cp.fork(childFile, [], { silent: true }); child.once('error', reject); child.once('close', resolve); }),",
    "]).then(() => console.log('ALL_UNSUPPORTED_APIS_COMPLETE')).catch((error) => { console.error(error); process.exitCode = 1; });",
  ].join("\n");
  const result = await runPreloadFixture(evidenceRoot, { configText: "", bodySource });
  const frames = result.control.trim().split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
  const nativeObservation = {
    exitCode: result.code,
    bodyCompleted: /ALL_UNSUPPORTED_APIS_COMPLETE/.test(result.stdout),
    descendantFrames: frames.filter((frame) => frame.type === "descendant_process"),
  };
  proof.mark("I:69–74", "each unsupported process API preserves its original natural behavior and disarms coverage", nativeObservation);
  assert.equal(result.code, 0, result.stderr);
  assert.equal(nativeObservation.bodyCompleted, true);
  assert.ok(nativeObservation.descendantFrames.length >= 1);
  return nativeObservation;
}

