async function runMainIntegration(selector, sites, evidenceRoot, proof) {
  const child = spawn(process.execPath, [path.join(ROOT, "tests", "test-2026-09-21-no-output.cjs"), selector], {
    cwd: ROOT,
    env: {
      ...process.env,
      PI_CODING_AGENT_DIR: path.join(evidenceRoot, "agent"),
      PI_ORCHESTRATOR_RUNS_ROOT: path.join(evidenceRoot, "runs"),
      PI_ORCHESTRATOR_NEXT_RUNS_ROOT: path.join(evidenceRoot, "next"),
      PI_ORCHESTRATOR_TEST_RUNS_OWNER: evidenceRoot,
      PI_OFFLINE: "1",
    },
    stdio: ["ignore", "pipe", "pipe"],
    windowsHide: true,
    detached: false,
  });
  let stdout = "";
  let stderr = "";
  child.stdout.on("data", (chunk) => { stdout += chunk; });
  child.stderr.on("data", (chunk) => { stderr += chunk; });
  const code = await new Promise((resolve, reject) => {
    child.once("error", reject);
    child.once("close", resolve);
  });
  fs.writeFileSync(path.join(evidenceRoot, "suite-stdout.log"), stdout);
  fs.writeFileSync(path.join(evidenceRoot, "suite-stderr.log"), stderr);
  fs.writeFileSync(path.join(evidenceRoot, "suite-command.json"), JSON.stringify({
    command: [process.execPath, path.join(ROOT, "tests", "test-2026-09-21-no-output.cjs"), selector],
    originalExitCode: code, evidenceRoot, stdoutSha256: sha256(Buffer.from(stdout)), stderrSha256: sha256(Buffer.from(stderr)),
  }, null, 2));
  assert.equal(code, 0, `${selector} actual monitor dispatch failed naturally\n${stderr.slice(-4096)}`);
  assert.match(stdout, /PASS item3/, `${selector} did not report its actual dispatch assertion marker`);
  const observation = {
    selector,
    exitCode: code,
    stdoutBytes: Buffer.byteLength(stdout),
    stderrBytes: Buffer.byteLength(stderr),
    stdoutSha256: sha256(Buffer.from(stdout)),
    passMarkers: stdout.split(/\r?\n/).filter((line) => line.startsWith("PASS item3")),
  };
  for (const site of sites) proof.mark(site, `${selector} actual Pi/AgentSession monitor dispatch assertion`, observation);
  return observation;
}

