  if (recoveryFailures.length > 0) console.error(`OWNERSHIP_ENUMERATION_RECOVERY_FAILURES ${JSON.stringify(recoveryFailures.map(serializeFailure), null, 2)}`);
  const allFailures = [...failures, ...fixtureFailures, ...recoveryFailures];
  if (allFailures.length > 0) {
    throw new AggregateError(allFailures.map((failure) => failure.error),
      `ownership enumeration failed product=${failures.length} fixture=${fixtureFailures.length} recovery=${recoveryFailures.length}`);
  }
  passed = true;
  console.log(`PASS item3 ownership enumeration rows=${SITE_MANIFEST.length} cases=${observations.size}`);
